public class InnerDataTransformationProfileSourceFactory(Action<Humidifier.HealthLake.DataTransformationProfileTypes.Source> factoryAction = null) : SubResourceFactory<Humidifier.HealthLake.DataTransformationProfileTypes.Source>
{

    internal InnerDataTransformationProfileProfileMappingSourceFactory ProfileMappingFactory { get; set; }

    internal InnerDataTransformationProfileStarterProfileSourceFactory StarterProfileFactory { get; set; }

    internal InnerDataTransformationProfileExistingVersionedProfileSourceFactory ExistingVersionedProfileIdFactory { get; set; }

    protected override Humidifier.HealthLake.DataTransformationProfileTypes.Source Create()
    {
        var sourceResult = CreateSource();
        factoryAction?.Invoke(sourceResult);

        return sourceResult;
    }

    private Humidifier.HealthLake.DataTransformationProfileTypes.Source CreateSource()
    {
        var sourceResult = new Humidifier.HealthLake.DataTransformationProfileTypes.Source();

        return sourceResult;
    }
    public override void CreateChildren(Humidifier.HealthLake.DataTransformationProfileTypes.Source result)
    {
        base.CreateChildren(result);

        result.ProfileMapping ??= ProfileMappingFactory?.Build();
        result.StarterProfile ??= StarterProfileFactory?.Build();
        result.ExistingVersionedProfileId ??= ExistingVersionedProfileIdFactory?.Build();
    }

} // End Of Class

